<script setup lang="ts">
import { ref, onMounted, nextTick, computed } from 'vue'
import { api } from '../api'
import { courseContent } from '../courseContent'
import { useCourseScope } from '../useCourseScope'
import { useSession } from '../stores/session'
import Icon from '../components/Icon.vue'
const scope=useCourseScope()
const webEnabled=ref(localStorage.getItem('zhima-web-search')!=='false')
const basisLabels:Record<string,string>={'course+web':'课程资料＋网页补充',course:'课程资料回答',web:'网页辅助回答',model:'模型知识回答',demo:'规则演示'}
function searchLabel(m:any){const status=m.web_search?.status;return status==='success'?'已联网检索':status==='failed'?'联网暂不可用，已继续回答':status==='empty'?'未找到合适网页，已继续回答':status==='disabled'?'本次未联网':''}
function setWeb(){localStorage.setItem('zhima-web-search',String(webEnabled.value))}
const session=useSession(), conversations=ref<any[]>([]), messages=ref<any[]>([]), input=ref(''), busy=ref(false), historyLoading=ref(false)
const conversationId=ref<number|null>(null), scroll=ref<HTMLElement>(), source=ref<any>(null), drawer=ref(false), lastQuestion=ref(''), hintLevel=ref(1)
async function list() { const data=await api.get(`/courses/${scope.courseId}/conversations`); if(scope.active())conversations.value=data }
onMounted(async()=>{await list();try{const health=await api.get('/health');if(scope.active()&&health.web_search_enabled===false)webEnabled.value=false}catch{}})
async function load(id:number) { if(busy.value||historyLoading.value)return; historyLoading.value=true; try { const r=await api.get(`/conversations/${id}`); if(!scope.active())return; conversationId.value=id; messages.value=r.messages; lastQuestion.value=[...r.messages].reverse().find((m:any)=>m.role==='user')?.content||''; hintLevel.value=[...r.messages].reverse().find((m:any)=>m.role==='assistant')?.hint_level||1; await down() } finally { historyLoading.value=false } }
async function down() { await nextTick(); if(scroll.value) scroll.value.scrollTop=scroll.value.scrollHeight }
function newChat() { if(busy.value||historyLoading.value)return; conversationId.value=null; messages.value=[]; input.value=''; hintLevel.value=1 }
async function send(question?:string, level=1) {
  const text=(question||input.value).trim(); if(!text||busy.value||historyLoading.value) return
  busy.value=true; input.value=''; messages.value.push({role:'user',content:text,id:'temp-'+Date.now()}); await down()
  try { const result=await api.post(`/courses/${scope.courseId}/chat`,{question:text,conversation_id:conversationId.value,hint_level:level,web_search:webEnabled.value}); if(!scope.active())return; conversationId.value=result.conversation_id; messages.value.push(result.answer); lastQuestion.value=text; hintLevel.value=level; await list() } catch { messages.value.pop(); input.value=text } finally { busy.value=false; await down() }
}
function showSource(c:any) { source.value=c; drawer.value=true }
const prompts=computed(()=>courseContent[scope.courseId]?.prompts||[])
</script>
<template>
  <div class="page-heading"><div><span class="eyebrow">ASK · THINK · UNDERSTAND</span><h1>让好奇，有处安放</h1><p>结合课程资料与相关网页回答，也可以像普通大模型一样交流其他问题。</p></div><span class="tag blue"><Icon name="badge" :size="14" />回答来源可追溯</span></div>
  <section class="chat-layout panel"><aside class="chat-history"><button class="btn btn-primary" :disabled="busy||historyLoading" @click="newChat"><Icon name="plus" :size="17" />开启新对话</button><span class="nav-group">我的课程对话</span><button v-for="c in conversations" :key="c.id" :class="['history-item',{selected:conversationId===c.id}]" :disabled="busy||historyLoading" @click="load(c.id)"><Icon name="chat" :size="16" /><span>{{ c.title }}</span></button><p v-if="!conversations.length" class="small muted history-empty">你的每一次思考<br>都会被好好保存。</p><div class="chat-privacy"><Icon name="shield" :size="16" /><span>对话仅自己可见<br>课程优先 · 联网补充</span></div></aside><div class="chat-main"><div class="chat-header"><span class="assistant-avatar"><Icon name="bot" :size="22" /></span><div><b>智码 · 课程助教</b><small><span class="status-dot"></span>陪你思考，帮你理解</small></div><span class="chat-course-tag">{{ session.course?.code }}</span></div>
      <div ref="scroll" v-loading="historyLoading" class="chat-messages"><div v-if="!messages.length" class="chat-welcome"><span class="welcome-icon"><Icon name="sparkle" :size="34" /></span><h2>今天，想弄懂什么？</h2><p>可以直接提问，也可以带上你的代码和思考。<br>课程问题结合讲义与网页；其他问题也能直接交流。</p><div class="prompt-grid"><button v-for="(p,i) in prompts" :key="p" @click="send(p)"><Icon :name="['database','code','layers','book'][i]" :size="19" /><span>{{ p }}</span><Icon name="arrowUp" :size="15" /></button></div><div class="welcome-note"><Icon name="file" :size="15" />课程资料＋按需联网＋模型知识 · 来源分别标注</div></div>
        <div v-for="m in messages" :key="m.id" :class="['message',m.role]"><span class="message-avatar" :class="m.role==='assistant'?'ai-avatar':''"><Icon v-if="m.role==='assistant'" name="sparkle" :size="18" /><template v-else>{{ session.user?.name?.slice(0,1) }}</template></span><div class="message-body"><div class="message-meta">{{ m.role==='assistant'?'智码助教':session.user?.name }}<span v-if="m.role==='assistant'">{{ m.mode==='demo'?'规则演示反馈':basisLabels[m.answer_basis]||'DeepSeek 生成' }}</span></div><div class="message-bubble">{{ m.content }}</div><p v-if="m.role==='assistant'&&searchLabel(m)" class="small muted answer-search-status" :title="m.web_search?.detail">{{ searchLabel(m) }}</p><div v-if="m.citations?.length" class="citation-list"><div class="citation-label"><Icon name="badge" :size="14" />回答来源</div><button v-for="(c,i) in m.citations" :key="i" data-testid="citation" @click="showSource(c)"><span>{{ c.number||Number(i)+1 }}</span><Icon :name="c.source_type==='web'?'external':'file'" :size="14" /><b>{{ c.title||c.filename }}</b><small>{{ c.source_type==='web'?'网页搜索摘要':c.location }}</small><Icon name="external" :size="13" /></button></div></div></div>
        <div v-if="busy" class="message assistant"><span class="message-avatar ai-avatar"><Icon name="sparkle" :size="18" /></span><div class="thinking"><i></i><i></i><i></i><span>{{ webEnabled?'正在查阅资料与网页，并思考回答…':'正在思考回答…' }}</span></div></div>
      </div><div class="chat-composer"><div v-if="messages.length&&lastQuestion&&hintLevel<3" class="chat-followup"><button class="text-link" :disabled="busy" @click="send(lastQuestion,hintLevel+1)"><Icon name="bulb" :size="15" />进一步提示</button><span class="small muted">先想一想，再展开下一步</span></div><div class="composer-box"><textarea v-model="input" maxlength="2000" data-testid="chat-input" placeholder="输入任何问题，也可以粘贴代码或继续追问…" rows="2" @keydown.enter.exact.prevent="send()"></textarea><div class="composer-bottom"><label class="web-search-toggle"><input v-model="webEnabled" type="checkbox" aria-label="联网补充" @change="setWeb" />联网补充</label><button class="send-button" aria-label="发送问题" data-testid="chat-send" :disabled="busy||!input.trim()" @click="send()"><Icon name="send" :size="18" /></button></div></div><p class="composer-note">Enter 发送 · Shift + Enter 换行<span>课程、网页与模型知识分别标注；重要结论请核对来源。</span></p></div>
    </div></section>
  <el-drawer v-model="drawer" title="回答引用来源" size="500px"><template v-if="source?.source_type==='web'"><span class="tag blue">网页搜索摘要</span><h2 class="source-title">{{ source.title }}</h2><p class="small muted">此处保存搜索当时取得的摘要，网页内容可能变化；摘要不等于完整正文。</p><a class="text-link" :href="source.url" target="_blank" rel="noopener noreferrer">{{ source.url }}</a><h4 class="mt24">搜索摘要</h4><div class="source-text">{{ source.text }}</div><a class="btn btn-soft" :href="source.url" target="_blank" rel="noopener noreferrer"><Icon name="external" :size="16" />打开来源网页</a></template><template v-else-if="source"><span class="tag blue"><Icon name="file" :size="14" />{{ source.location }}</span><h2 class="source-title">{{ source.filename }}</h2><p class="small muted">此处保留回答当时的来源快照，便于核对。</p><h4 class="mt24">来源原文</h4><div class="source-text">{{ source.text }}</div><button class="btn btn-soft" @click="api.download(source.material_id,source.filename)"><Icon name="download" :size="16" />下载原始资料</button><p class="small muted mt16">若教师已删除该资料，历史快照仍可查看，原文件不可下载。</p></template></el-drawer>
</template>
